import { BlendLevel, GRReelEvent, IMapIndex, IReelStopData, IReelValidation, ISpeedControl } from './../types/index';
import { SpinState, ISize } from '../types/index';
import { Container, Graphics, Rectangle, Sprite, Texture, Ticker } from 'pixi.js';
import gsap, { TweenLite, Elastic } from 'gsap';
import { delay } from './utils/GRUtils';
import { GRSymbolView } from './GRSymbolView';
import { GRService } from './GRService';
import { GREvents } from '../events';

const DEFAULT_SPEED_STEP: number = 1;
export class GRReelView<GenericSymbol extends GRSymbolView> extends Container {

    public eventFire: GRReelEvent;
    public reelIndex: number = 0;

    protected _symbols: GenericSymbol[] = [];
    protected _symbolHolder: Container;
    protected _service: GRService;
    protected _events: GREvents;
    protected _topOffset: number = 0;
    protected _bottomOffset: number = 0;
    protected _reelSize: number = 0;
    protected _totalSymbolCount: number = 0;
    protected _reelMap: number[] = [];
    protected _reelMapClone: number[] = [];

    private _reelBounds: Rectangle;
    private _viewMask: Container;
    private _viewMaskYOffset: number = 0;
    private _reelMapTargetIndex: number = 0;
    private _reelFrameTransform: Rectangle;
    private _reelSpinState: SpinState = SpinState.STOPPED;

    private _speedControl: ISpeedControl = {
        speed: 0,
        speedLimit: 0,
        increment: 0,
        decrement: 0,
        incrementStep: 0,
        decrementStep: 0,
        accelerationLimit: 0,
        decelerationLimit: 0,
        speedLimitDecreased: false,
        reset: (): void => {
            this._speedControl.increment = 0;
            this._speedControl.decrement = 0;
            this._speedControl.speed = 0;
            this._speedControl.speedLimitDecreased = false;
        },
        calculateSpeed: (delta: number): void => {
            if (this._speedControl.speed < this._speedControl.speedLimit) {
                this._speedControl.calculateIncrement();
                this._speedControl.speed += this._speedControl.increment * delta;
                if (this._speedControl.speed > this._speedControl.speedLimit) {
                    this._speedControl.speed = this._speedControl.speedLimit;
                }
            } else if (this._speedControl.speed > this._speedControl.speedLimit) {
                this._speedControl.calculateDecrement();
                this._speedControl.speed -= this._speedControl.decrement * delta;
                if (this._speedControl.speed <= this._speedControl.speedLimit) {
                    this._speedControl.speed = this._speedControl.speedLimit;
                }
            }
        },
        calculateIncrement: (): void => {
            if (this._speedControl.increment > this._speedControl.accelerationLimit) {
                this._speedControl.increment = this._speedControl.accelerationLimit;
            } else {
                this._speedControl.increment += this._speedControl.incrementStep;
            }
        },
        calculateDecrement: (): void => {
            if (this._speedControl.decrement > this._speedControl.decelerationLimit) {
                this._speedControl.decrement = this._speedControl.decelerationLimit;
            } else {
                this._speedControl.decrement += this._speedControl.decrementStep;
            }
        },
    };

    private _reelMapCurrentIndex: IMapIndex = {
        value: 0,
        increase: (): void => {
            if (this._reelMapCurrentIndex.value < this._reelMap.length) {
                this._reelMapCurrentIndex.value++;
            } else {
                this._reelMapCurrentIndex.value = 1;
            }
            this.setAndPosition();
        },
        decrease: (): void => {
            if (this._reelMapCurrentIndex.value > 0) {
                this._reelMapCurrentIndex.value--;
            } else {
                this._reelMapCurrentIndex.value = this._reelMap.length - 1;
            }
            this.setAndPosition();
        }
    };

    private _reelValidation: IReelValidation = {
        validated: false,
        unvalidatedStepCount: 0,
        validate: (): void => {
            this._reelMap = [...this._reelMapClone];
            this._reelValidation.validated = true;
        },
        invalidate: (): void => {
            this._reelValidation.unvalidatedStepCount = 0;
            this._reelValidation.validated = false;
        },
        run: (): void => {
            if (this._reelValidation.validated) {
                return;
            }
            if (this._reelValidation.unvalidatedStepCount > this._totalSymbolCount) {
                this._reelValidation.validate();
                return;
            }
            this._reelValidation.unvalidatedStepCount++;
        }
    };

    constructor(SymbolType: { new(): GenericSymbol }, service: GRService, reelSize: number, reelIndex: number) {
        super();
        this._service = service;
        this.reelIndex = reelIndex;
        this._reelSize = reelSize;
        this._topOffset = service.coreSettings.topOffset;
        this._bottomOffset = service.coreSettings.bottomOffset;
        this._totalSymbolCount = this._topOffset + this._bottomOffset + this._reelSize;

        // initialize event system
        this._events = new GREvents();
        this.eventFire = { reelEvent: this._events.reelEvents, reelEffect: this._events.reelEffects };

        // setup reel
        this.buildReel(SymbolType);
        this.buildMask(this._service.coreSettings?.viewMaskTexture);

        // register and authenticate reel id.
        const registerResponse = service.commands.registerReel(reelIndex);
        if (!registerResponse.success) {
            return;
        }

        // add reel update() to shared pixi ticker.
        const ticker: Ticker = Ticker.shared;
        ticker.add((ticker) => { this.update(ticker.deltaTime); });

        const accelerationSteps = this._service.reelSettings.speedSettings.acceleration.steps;
        const decelerationSteps = this._service.reelSettings.speedSettings.deceleration.steps;
        this._speedControl.incrementStep = accelerationSteps[this.reelIndex] ?? accelerationSteps[accelerationSteps.length - 1] ?? DEFAULT_SPEED_STEP;
        this._speedControl.decrementStep = decelerationSteps[this.reelIndex] ?? decelerationSteps[decelerationSteps.length - 1] ?? DEFAULT_SPEED_STEP;

        this.addBindings();
        this.addPresets();
    }

    /** 
     example: getGridAtVisible(0) will return the first symbol visible from the top of the reel
    */
    public getGridAtVisible(grid: number): GenericSymbol {
        return this._symbols[grid + this._topOffset];
    }

    public preDraw(): void {
        this.visible = false;
        this._symbols.forEach((symbol: GenericSymbol) => {
            symbol.preDraw();
        });
    }

    public postDraw(): void {
        this.visible = true;
        this._symbols.forEach((symbol: GenericSymbol) => {
            symbol.postDraw();
        });
    }

    public enableMask(): void {
        this._viewMask.visible = true;
        this._symbolHolder.mask = this._viewMask;
    }

    public disableMask(): void {
        this._viewMask.visible = false;
        this._symbolHolder.mask = null;
    }

    /**
     * Force applies a new startPosition
     * For cases where a startPosition change is needed without changing the reel description
     */
    public forceApplyStartPositionChange(): void {
        this._reelMapCurrentIndex.value = this._service.model.startPosition[this.reelIndex];
        this.setAndPosition();
    }

    /**
     * Rebuilds the mask at the current dimensions
     * Useful for cases where the frameTransform has changed after construction
     */
    public rebuildMask(): void {
        this.removeChild(this._viewMask);
        this.buildMask(this._service.coreSettings?.viewMaskTexture);
    }

    protected buildReel(SymbolType: { new(): GenericSymbol }): void {
        this._symbolHolder = new Container();
        this._symbolHolder.sortableChildren = this._service.coreSettings.allowZIndexSymbolSorting;
        this.addChild(this._symbolHolder);

        // build each symbol of the reel
        for (let $symbolIndex: number = 0; $symbolIndex < this._totalSymbolCount; $symbolIndex++) {
            const symbol: GenericSymbol = new SymbolType();
            symbol.initialiseSymbol(this._service);
            this._symbolHolder.addChild(symbol);
            symbol.symbolData.index = $symbolIndex - this._topOffset;
            symbol.parentReelData.index = this.reelIndex;
            symbol.x = this.frameTransform.width * 0.5;
            symbol.width = this.frameTransform.width;
            symbol.scale.y = symbol.scale.x;
            this._symbols.push(symbol);
        }
    }

    protected getTargetPositionY(offset: number) {
        //return postion of y axis in reel stack depending on symbol index
        const symbolStackPosition = (this.symbolHeight * offset);
        const symbolYCenter = (this.symbolHeight * 0.5);
        const stackOffset = -(this.symbolHeight * (this._topOffset - 1));
        return (stackOffset + symbolStackPosition - symbolYCenter);
    }

    private update(delta: number): void {
        this.movementUpdate(delta);
    }

    private async beginReelSpin(): Promise<void> {

        // injects current display if snapshot is enabled
        this.injectCurrentDisplay();

        // sets symbol parent data
        this._symbols.forEach((symbol: GenericSymbol) => {
            gsap.killTweensOf(symbol);
            symbol.parentReelData.spinning = true;
        });

        // validate position and speed
        this.setAndPosition();
        this._speedControl.reset();
        this._speedControl.speed = this._service.reelSettings.rollbackSpeed;

        // reel stagger effect
        await delay(this._service.reelSettings.reelStartDelay * this.reelIndex);

        // set reel state and block interactive activity
        this._reelSpinState = SpinState.SPINNING;
        this.interactiveChildren = false;
        this.onSpinState$(this._service.model.spinState);
    }

    private translateReelIndex(localPosition: number, globalPosition: number, reelMap: number[] = this._reelMap): number {
        const calibratedPostion: number = (localPosition + globalPosition) - this._topOffset;

        if (calibratedPostion >= reelMap.length) {
            return calibratedPostion - reelMap.length;
        }
        if (calibratedPostion < 0) {
            return calibratedPostion + reelMap.length;
        }

        // global  local
        //   50    (0) (x) (x)
        //  ----   -------------
        //   51    (1) (x) (x)
        //   52    (2) (x) (x)
        //   0     (3) (x) (x)
        //  ----   -------------
        //   1     (4) (x) (x)

        return calibratedPostion;
    }

    private buildMask(maskTexture: Texture | undefined): void {
        this._reelBounds = new Rectangle(-this.frameTransform.width * 0.5, 0, this.frameTransform.width * 2, this.symbolHeight * this._reelSize);

        const size: ISize = { width: this._reelBounds.width * 2, height: this._reelBounds.height };
        let graphicsMask: Sprite | Graphics;

        if (maskTexture) {
            graphicsMask = new Sprite(maskTexture);
            graphicsMask.width = size.width;
            graphicsMask.height = size.height;
            graphicsMask.anchor.set(0.5, 0);
            graphicsMask.y += this._viewMaskYOffset;
        } else {
            graphicsMask = new Graphics();
            graphicsMask.clear();
            graphicsMask.lineStyle(2, 0x0000FF, 1);
            graphicsMask.beginFill(0xFF700B, 1);
            graphicsMask.drawRect(this._reelBounds.x * 2, this._reelBounds.y + this._viewMaskYOffset, size.width, size.height);
            graphicsMask.endFill();
        }

        this._viewMask = graphicsMask;
        this.addChild(this._viewMask);
        this._symbolHolder.mask = this._viewMask;
    }

    private applyReelStopEffect(inertia: number): void {
        // cycle stop effect on all symbols
        this._symbols.forEach((symbol: GenericSymbol, $index: number) => {
            const endPosition: number = (this.symbolHeight * $index) - (this.symbolHeight * 0.5) - (this.symbolHeight * (this._topOffset - 1));
            symbol.y = endPosition;
            symbol.parentReelData.spinning = false;
            symbol.parentReelData.speed = 0;
            this.eventFire.reelEffect.REEL_STOP_EFFECT({ symbol, inertia, endPosition });
        });
    }

    private defaultSpinBounceEffect(reelStopData: IReelStopData): void {
        const bounce: number = reelStopData.inertia * this._service.reelSettings.bounceSettings.elasticStopIntensity;
        reelStopData.symbol.y += bounce;

        TweenLite.to(reelStopData.symbol, this._service.reelSettings.bounceSettings.elasticStopDuration, {
            ease: Elastic.easeOut.config(this._service.reelSettings.bounceSettings.elasticBounceAmplitude, this._service.reelSettings.bounceSettings.elasticBouncePeriod),
            y: reelStopData.endPosition
        });
    }

    private movementUpdate(delta: number): void {

        if (this._reelSpinState === SpinState.STOPPED) {
            return;
        }

        if (this._reelMapCurrentIndex.value === this._reelMapTargetIndex && this._reelSpinState === SpinState.WAITING_TO_STOP) {
            this._reelSpinState = SpinState.STOPPED;
            this._reelValidation.validate();
            this.setAndPosition(true);
            this.applyReelStopEffect(this._speedControl.speed);
            this.interactiveChildren = true;
            this._speedControl.reset();
            this.eventFire.reelEvent.ON_REEL_STOP();
            this._service.commands.stepSpinSequence();

        } else {

            this.eventFire.reelEvent.ON_REEL_SPINNING_BEFORE_TICK();
            // update reel speed
            this._speedControl.accelerationLimit = this._service.reelSettings.speedSettings.acceleration.limit;
            this._speedControl.decelerationLimit = this._service.reelSettings.speedSettings.deceleration.limit;
            this._speedControl.calculateSpeed(delta);

            // position symbols on y axis
            this._symbols.forEach((symbol: GenericSymbol) => {
                symbol.y += this.speed * delta;
                symbol.parentReelData.speed = this.speed;
            });

            // work out current navigational map index
            const trackedSymbol: GenericSymbol = this.symbols[this._topOffset - 1];
            const lowerYBoundary: number = this.symbolHeight * 0.5;
            const upperYBoundary: number = -(this.symbolHeight * 1.5);
            if (trackedSymbol.y >= lowerYBoundary) {
                this._reelMapCurrentIndex.decrease();
            } else if (trackedSymbol.y <= upperYBoundary) {
                this._reelMapCurrentIndex.increase();
            }
            this.eventFire.reelEvent.ON_REEL_SPINNING_AFTER_TICK();
        }
    }

    private setAndPosition(setAsSpine: boolean = false): void {
        this._symbols.forEach((symbol: GenericSymbol, $symbolIndex: number) => {

            // set symbol position
            symbol.y = this.getTargetPositionY($symbolIndex);

            // detect if symbol is visible on screen
            const upperVisibleIndexBoundary: number = 0;
            const lowerVisibleIndexBoundary: number = this.reelSize - this._bottomOffset;
            symbol.symbolData.onScreen = symbol.symbolData.index >= upperVisibleIndexBoundary && symbol.symbolData.index <= lowerVisibleIndexBoundary ? true : false;

            this.eventFire.reelEvent.ON_SYMBOL_POSITION_SET_BEFORE_TICK(symbol);

            // set symbol skin
            const skin: number = Math.abs(this._reelMap[this.translateReelIndex($symbolIndex, this._reelMapCurrentIndex.value)]);
            symbol.symbolData.skin = skin;
            if (setAsSpine) {
                symbol.setAnimationSkin();
            } else {
                symbol.setStaticSkin();
            }

            this.eventFire.reelEvent.ON_SYMBOL_POSITION_SET_AFTER_TICK(symbol);
        });

        this._reelValidation.run();
    }

    private blendTrack(): void {
        if (this._service.reelSettings.stoppingBlendMode === BlendLevel.none) {
            return;
        }
        if (this._service.reelSettings.stoppingBlendMode === BlendLevel.jump) {
            this._reelMapCurrentIndex.value = this._reelMapTargetIndex + this._totalSymbolCount;
            return;
        }
        if (this._service.reelSettings.stoppingBlendMode === BlendLevel.onlySlow && !this._speedControl.speedLimitDecreased) {
            return;
        }
        // inject validated target display symbols to navigational reel map
        for (let $symbolIndex: number = 0; $symbolIndex < this._totalSymbolCount; $symbolIndex++) {
            const calibratedCurrentPosition: number = this.translateReelIndex($symbolIndex, this._reelMapCurrentIndex.value);
            const trackSnippet: number = this._reelMapClone[this.validatedCloneIndex(calibratedCurrentPosition)];
            const lineUpPosition: number = $symbolIndex + this._totalSymbolCount;
            const calibratedTargetPosition = this.translateReelIndex(lineUpPosition, this._reelMapTargetIndex);
            this._reelMap[calibratedTargetPosition] = trackSnippet;
        }
        this._reelMapCurrentIndex.value = this._reelMapTargetIndex + this._totalSymbolCount;
    }

    private validatedCloneIndex(index: number): number {
        const validRange: number = this._reelMapClone.length - 1;
        if (index > validRange) {
            const indexOffset = (index - validRange) - 1;
            return indexOffset;
        }
        return index;
    }

    private injectCurrentDisplay(): void {
        // check if feature is enabled
        if (!this._service.coreSettings.snapshotInjection) {
            return;
        }
        // copy symbols on show
        const snapshot: number[] = [];
        this._symbols.forEach((symbol: GenericSymbol) => {
            const skin = symbol.symbolData.skin;
            snapshot.unshift(skin);
        });
        // inject to navigational reel map
        const snapshotReel: number[] = [...this._reelMapClone];
        snapshot.reverse();
        for (let index = 0; index < snapshot.length; index++) {
            const target = this.translateReelIndex(this._reelMapCurrentIndex.value, index, snapshotReel);
            snapshotReel.splice(target, 0, snapshot[index]);
        }
        this._reelMap = snapshotReel;
        this._reelValidation.invalidate();
        this.setAndPosition();
    }

    private onForceDisplayReel$(displayReels: [][]): void {
        const displayReel: number[] = displayReels[this.reelIndex];
        const includesOffset: boolean = displayReel.length > this.reelSize;
        if (!includesOffset) {
            // check we have data for each symbol
            if (displayReel.length !== this.reelSize) {
                console.warn('missing symbol data');
                return;
            }
            // only set visible symbols
            for (let $symbolIndex: number = 0; $symbolIndex < this._reelSize; $symbolIndex++) {
                const symbol: GenericSymbol = this.getGridAtVisible($symbolIndex);
                symbol.symbolData.skin = displayReel[$symbolIndex];
                symbol.setStaticSkin();
            }
        } else {
            // check we have data for each symbol
            if (displayReel.length !== this._totalSymbolCount) {
                console.warn('includeOffset has been activated, but missing symbol data');
                return;
            }
            // set all offscreen and visible symbols
            this._symbols.forEach((symbol: GenericSymbol, $symbolIndex: number) => {
                symbol.symbolData.skin = displayReel[$symbolIndex];
                symbol.setStaticSkin();
            });
        }
    }

    private onReelSetupUpdate$(reels: number[][]): void {
        // check reel has data
        if (reels.length === 0) {
            return;
        }
        // check if new setup is a duplicate 
        if (this._reelMap.toString() === reels[this.reelIndex].toString()) {
            return;
        }
        //update reel data
        this._reelMap = [...reels[this.reelIndex]];
        this._reelMapClone = [...this._reelMap];
        this._reelMapCurrentIndex.value = this._service.model.startPosition[this.reelIndex];
        this.setAndPosition();
    }

    private onSpinState$(spinStates: number[]): void {
        // begin spin
        const modelSpinState: SpinState = spinStates[this.reelIndex];
        if (modelSpinState === SpinState.SPINNING && this._reelSpinState === SpinState.STOPPED) {
            this.eventFire.reelEvent.ON_BEGIN_SPIN_BEFORE_TICK();
            this.beginReelSpin();
        }
        // end spin
        if (modelSpinState === SpinState.STOPPED && this._reelSpinState === SpinState.SPINNING) {
            this._reelSpinState = SpinState.WAITING_TO_STOP;
            this._reelMapTargetIndex = this._service.model.targetPosition[this.reelIndex];
            this.blendTrack();
        }
    }

    private onReelSpeedLimit$(speedValues: number[]): void {
        const reelSpeed: number = speedValues[this.reelIndex];
        if (this._speedControl.speedLimit > reelSpeed) {
            this._speedControl.speedLimitDecreased = true;
        }
        this._speedControl.speedLimit = reelSpeed;
    }

    public get speed(): number {
        return this._speedControl.speed;
    }

    public get reelSize(): number {
        return this._reelSize;
    }

    public get reelBounds(): Rectangle {
        return this._reelBounds;
    }

    public get isSpinning(): boolean {
        return this._reelSpinState === SpinState.STOPPED ? false : true;
    }

    public get symbols(): GenericSymbol[] {
        return this._symbols;
    }

    public get symbolHeight(): number {
        return this.frameTransform.height + this._service.reelSettings.symbolVerticalPadding;
    }

    public set reelFrameTransform(frameTransform: Rectangle) {
        this._reelFrameTransform = frameTransform;
        this.setAndPosition();
    }

    protected get frameTransform(): Rectangle {
        return this._reelFrameTransform ? this._reelFrameTransform : this._service.symbolSettings.frameTransfrom;
    }

    protected addPresets(): void {
        this.eventFire.reelEffect.REEL_STOP_EFFECT = (reelStopData: IReelStopData): void => {
            this.defaultSpinBounceEffect(reelStopData);
        };
    }

    protected addBindings(): void {
        this._service.model.bindToValue(this, () => this._service.model.spinState, () => this.onSpinState$);
        this._service.model.bindToValue(this, () => this._service.model.spinSpeedValues, () => this.onReelSpeedLimit$);
        this._service.model.bindToValue(this, () => this._service.model.onScreenReels, () => this.onReelSetupUpdate$, true);
        this._service.model.bindToValue(this, () => this._service.model.displayReels, () => this.onForceDisplayReel$);
    }
}
